\begin{theorem}[The rank-three bundle $P$]\hypertarget{tag-02QW}{}\label{night:P1.5}
\StatementRecord{night:P1.5}{proved}{02QW}{the definitions and constructions stated in the proof}
The wedge map from
$\ell_0\otimes(\mathcal H_{\mathrm{dR}}/\ell_0)$, followed by
projection modulo the nondegenerate polarization bivector, is
injective and has rank-three image. This image defines the bundle
$P$ used in the period construction.
\end{theorem}
\begin{proof}
\begin{enumerate}[label={$\langle1\rangle$\arabic*.}]
\item There is an injective holomorphic map
\[
\ell_0\otimes(\mathcal H_{\mathrm{dR}}/\ell_0)
 \longrightarrow\bigwedge^2\mathcal H_{\mathrm{dR}},\quad
u\otimes[v]\longmapsto u\wedge v.
\]
Every nonzero image vector is decomposable and has wedge square zero;
$\omega^2\ne0$.  Projection modulo $\mathcal O\omega$ is therefore
injective on its rank-three image.  This defines the bundle $P$ used below.

\end{enumerate}
\end{proof}

new_text:
\begin{theorem}[The rank-three bundle $P$]\hypertarget{tag-02QW}{}\label{night:P1.5}
\StatementRecord{night:P1.5}{proved}{02QW}{the definitions and constructions stated in the proof}
The wedge map from
$\ell_0\otimes(\mathcal H_{\mathrm{dR}}/\ell_0)$, followed by
projection modulo the nondegenerate polarization bivector, is
injective and has rank-three image. This image defines the bundle
$P$ used in the period construction.
Moreover
$P\cong\mathcal O\oplus T^2\oplus T^4$,
$H^1(P^\vee)=0$, and $H^0(P^\vee)$ is the one-dimensional
space of contractions. Its inclusion into the rank-five quotient
lifts holomorphically to the rank-six extension.
\end{theorem}
\begin{proof}
On the root curve of orders five and eight, let $\mathcal H_D$ be
the logarithmic de Rham bundle of the pencil. Its Hodge subbundle is
$\mathcal E=T^3\oplus T$, with $\ell=T^3$. The polarization identifies
$\mathcal H_D/\mathcal E$ with $\mathcal E^\vee$. This remains true
at the node: the dualizing differentials have independent limits,
and their isotropic pairing extends there holomorphically.
The primitive projection $p$ and the marked extension give
\begin{align}
 0&\longrightarrow\mathbb C e\longrightarrow\mathcal V
   \longrightarrow\mathcal W\longrightarrow0,
 \hypertarget{tag-02EK}{}\label{maps:eq:F.14}\\
 P&=p(\ell\wedge\mathcal H_D).
 \hypertarget{tag-02EL}{}\label{maps:eq:F.15}
\end{align}
In logarithmic frames the first sequence extends over the cusp,
since the nilpotent exponential commutes with its inclusion and
quotient. It extends equivariantly over the finite root charts.
Every nonzero vector in $\ell\wedge\mathcal H_D$ is decomposable, whereas the polarization bivector has nonzero square. Thus primitive projection is injective there. The Hodge sequence therefore gives
\begin{equation}
 0\longrightarrow T^4\longrightarrow P
   \longrightarrow\mathcal O\oplus T^2\longrightarrow0.
 \hypertarget{tag-02EM}{}\label{maps:eq:F.16}
\end{equation}
For the coarse projection $\rho$, invariant sections in the two
root charts give
\begin{equation}
 \rho_*T^j=\mathcal O_{\mathbb P^1}
 \left(\left\lfloor\frac{2j}{5}\right\rfloor+
       \left\lfloor-\frac{3j}{8}\right\rfloor\right).
 \hypertarget{tag-02EN}{}\label{maps:eq:F.17}
\end{equation}
Finite-group averaging makes descent exact. For $j=\pm2,\pm4$
the degree is $-1$, so both cohomology groups vanish. Consequently
$P=\mathcal O\oplus T^2\oplus T^4$ and
$H^1(P^\vee)=0$. The pullback of \eqref{maps:eq:F.14} to $P$
splits holomorphically. Its splittings differ by $z\alpha e$,
since $H^0(P^\vee)=\mathbb C\alpha$.
\end{proof}

