\node[draw,rounded corners,minimum width=2.2cm,minimum height=.65cm] (TE) at (3.5,-1.25) {\hyperlink{main-V-E}{Theorem E}};
\node[draw,rounded corners,minimum width=2.2cm,minimum height=.65cm] (TF) at (7.0,-1.25) {\hyperlink{main-V-F}{Theorem F}};
\draw[->,semithick] (TB) to (TC);
\draw[->,semithick] (TA) to (TD);
\draw[->,semithick] (TB) to (TD);
\draw[->,semithick] (TC) to (TD);
\end{tikzpicture}
\caption{Dependencies among the main theorems; the table names the argument that carries each.}
\par\medskip
\begingroup\small
\begin{tabularx}{\textwidth}{@{}p{.10\textwidth}X@{}}
